'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './dot-field.css'

export type DotFieldProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Dot colour. */
    color?: string
    /** Spacing between dots in px. */
    gap?: number
    /** Seconds for the light to sweep across. */
    speed?: number
    paused?: boolean
}

const DotField = ({ color = 'rgba(148, 163, 184, 0.9)', gap = 18, speed = 9, paused = false, className, style, children, ...props }: DotFieldProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-dots', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-dots-color': color, '--rad-fx-dots-gap': `${gap}px`, '--rad-fx-dots-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-dots-base" aria-hidden="true" />
        <div className="rad-fx-dots-lit" aria-hidden="true" />
        <div className="rad-fx-dots-content">{children}</div>
    </div>
}

export default DotField

/* DotField: a dim dot grid with a soft pool of light drifting across it. */
.rad-fx-dots {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-dots-base,
.rad-fx-dots-lit {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background-image: radial-gradient(circle, var(--rad-fx-dots-color) 1px, transparent 1.5px);
    background-size: var(--rad-fx-dots-gap, 18px) var(--rad-fx-dots-gap, 18px);
}

.rad-fx-dots-base { opacity: 0.25; }

.rad-fx-dots-lit {
    mask-image: radial-gradient(circle at center, #000 0, transparent 70%);
    mask-size: 60% 90%;
    mask-repeat: no-repeat;
    mask-position: 0% 50%;
    animation: rad-fx-dots-sweep var(--rad-fx-dots-speed, 9s) ease-in-out infinite alternate;
}

.rad-fx-dots[data-state='paused'] .rad-fx-dots-lit { animation-play-state: paused; }

.rad-fx-dots-content { position: relative; }

@keyframes rad-fx-dots-sweep {
    0% { mask-position: 0% 20%; }
    50% { mask-position: 60% 80%; }
    100% { mask-position: 100% 30%; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-dots-lit { animation: none; mask-position: 50% 50%; }
}

[data-rad-fx-motion='reduce'] .rad-fx-dots-lit { animation: none; mask-position: 50% 50%; }
